#!/usr/bin/env python3
"""Generate the additive snapshot-size summary contract from canonical SQL."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
source = 'database/functions/scanning/admission.sql'
sql = (root/source).read_text()
start = sql.index('CREATE OR REPLACE FUNCTION public.get_scanner_summary(')
end = sql.index('END $$;', start) + len('END $$;')
(root/'supabase/migrations/20261026020000_scanner_auto_offline_summary.sql').write_text(
    '-- Generated by automation/assemble-scanner-auto-offline-migration.py. Do not edit.\n'
    + '-- Source: ' + source + '\n' + sql[start:end] + '\n')
